{"content":"import unittest

from proverb import proverb


class ProverbTest(unittest.TestCase):
    def test_no_items(self):
        self.assertEqual(proverb(), [])
        self.assertEqual(proverb(qualifier="horseshoe"), [])

    def test_single_item(self):
        self.assertEqual(proverb("nail"), ["And all for the want of a nail."])

    def test_full_proverb(self):
        self.assertEqual(
            proverb("nail", "shoe", "horse", "rider", "message", "battle", "kingdom"),
            [
                "For want of a nail the shoe was lost.",
                "For want of a shoe the horse was lost.",
                "For want of a horse the rider was lost.",
                "For want of a rider the message was lost.",
                "For want of a message the battle was lost.",
                "For want of a battle the kingdom was lost.",
                "And all for the want of a nail.",
            ],
        )

    def test_arbitrary_items(self):
        self.assertEqual(
            proverb("pin", "wheel"),
            [
                "For want of a pin the wheel was lost.",
                "And all for the want of a pin.",
            ],
        )

    def test_qualifier_only_changes_final_verse(self):
        self.assertEqual(
            proverb("nail", "shoe", qualifier="horseshoe"),
            [
                "For want of a nail the shoe was lost.",
                "And all for the want of a horseshoe nail.",
            ],
        )

    def test_single_item_with_qualifier(self):
        self.assertEqual(
            proverb("nail", qualifier="horseshoe"),
            ["And all for the want of a horseshoe nail."],
        )

    def test_empty_qualifier(self):
        self.assertEqual(proverb("nail", qualifier=""), proverb("nail"))


if __name__ == "__main__":
    unittest.main()
